{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Carfilzomib, a peptidic proteasome inhibitor sharing the Leu/Phe amide backbone with the query, did not suppress proteasome activity in rat brain after IV administration, indicating that this inhibitor chemotype is not readily able to access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "HSK21542, a peptide-like molecule with multiple amides and hydrophobic residues, exhibited a brain/plasma ratio of 0.001, demonstrating that high polar surface area and peptide character can lead to negligible CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "PPI-1019, a larger peptide, did cross the human BBB, but it lacks the boronic acid warhead and is structurally distinct; this provides only limited contradictory evidence for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The class-matched proteasome inhibitor evidence and the polar peptide evidence indicate poor CNS access; the few permeable peptide/boronate analogues are less transferable due to different transport mechanisms and structures. Therefore bortezomib is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct bortezomib brain/CSF pharmacokinetic measurement is present in the provided evidence set.",
    "Efflux-transporter status of bortezomib at the BBB is not directly tested in these records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

